package net.officefloor.hq.app.statement;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController;
import net.officefloor.hq.app.claim.ClaimController.ClaimResponse;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing each person's statements on a sheet, and taking or cancelling a person's statement. */
@RestController
@RequestMapping("/api/statements")
public class StatementController {

    public record ListStatementsRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    public record TakeStatementRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long personId) {
    }

    public record CancelStatementRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull Long personId) {
    }

    /**
     * A person's statement count, and the last statement's due-total ("n/a" when it had none) and
     * date; both none when no statement is left.
     */
    public record SummaryResponse(long personId, int count, String dueTotal, LocalDate date) {
    }

    public record TakenResponse(SummaryResponse summary, List<ClaimResponse> claims) {
    }

    private static SummaryResponse response(StatementService.Summary s) {
        if (s.last() == null) {
            return new SummaryResponse(s.personId(), s.count(), null, null);
        }
        return new SummaryResponse(s.personId(), s.count(), StatementService.money(s.last().getDueTotal()),
                s.last().getTakenOn());
    }

    private final StatementService service;

    public StatementController(StatementService service) {
        this.service = service;
    }

    @PostMapping("/list")
    public List<SummaryResponse> list(@Valid @RequestBody ListStatementsRequest req) {
        return service.list(req.sheet().trim()).stream().map(StatementController::response).toList();
    }

    @PostMapping("/take")
    public TakenResponse take(@Valid @RequestBody TakeStatementRequest req) {
        StatementService.Taken taken = service.take(req.sheet().trim(), req.user().trim(), req.personId());
        return new TakenResponse(response(taken.summary()),
                taken.claims().stream().map(ClaimController::response).toList());
    }

    @PostMapping("/cancel")
    public TakenResponse cancel(@Valid @RequestBody CancelStatementRequest req) {
        StatementService.Cancelled cancelled = service.cancel(req.sheet().trim(), req.user().trim(), req.personId());
        return new TakenResponse(response(cancelled.summary()),
                cancelled.claims().stream().map(ClaimController::response).toList());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A statement taken for a person: the sheet's today when it was taken, their due-total then (none
 * when it was n/a) and how many of their claims counted.
 */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    @Column(name = "due_total")
    private BigDecimal dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate takenOn, BigDecimal dueTotal, int claims) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.dueTotal = dueTotal;
        this.claims = claims;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaims() {
        return claims;
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** A sheet's statements, oldest first. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Statements on a sheet. Taking a person's statement records their due-total at that moment, taken
 * on the sheet's today (held to the sheet's cap), and binds every claim of theirs that counts (OPEN, PENDING or SETTLED, but not a held
 * person's OPEN or PENDING claims) to the figure it has then; a claim of theirs that does not count is unbound,
 * so its figure is live again. The late charge is never bound: the due-total includes each claim's charge on the day, but a claim is
 * bound to the rate figure under it, not the floored one (the floor is applied last, see {@link net.officefloor.hq.app.claim.LateCharge}).
 * A steward can cancel a person's last statement: the claims it bound are live again (a figure bound
 * by a statement before it is not restored), and the statement before it is the last one again.
 */
@Service
public class StatementService {

    /** A person's statements: how many, and the last one (none before the first). */
    public record Summary(long personId, int count, Statement last) {
    }

    /** A statement just taken, with the person's claims as it left them. */
    public record Taken(Summary summary, List<Claim> claims) {
    }

    /** A statement just cancelled: the person's statements left (none last when none are), and their claims. */
    public record Cancelled(Summary summary, List<Claim> claims) {
    }

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final RoleService roles;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            ClaimService claimService, RateRepository rates, SheetService sheets, Audit audit, RollupService rollup,
            RoleService roles) {
        this.roles = roles;
        this.rollup = rollup;
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Each person's statements on the sheet who has taken any. */
    @Transactional(readOnly = true)
    public List<Summary> list(String sheetId) {
        Map<Long, Summary> by = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            Summary was = by.get(s.getPersonId());
            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
        }
        return List.copyOf(by.values());
    }

    @Transactional
    public Taken take(String sheetId, String user, long personId) {
        roles.refuseViewer(sheetId, user);
        Person person = people.lockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        LocalDate today = sheets.today(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFigure = false;
        int counted = 0;
        for (Claim claim : theirs) {
            if (person.counts(claim, today)) {
                BigDecimal figure = claimService.figure(sheetId, person, claim);
                BigDecimal charged = claimService.charged(sheetId, person, claim);
                claim.bind(true, figure);
                if (charged != null) {
                    total = total.add(charged);
                    anyFigure = true;
                }
                counted++;
            } else {
                claim.bind(false, null);
            }
        }
        claims.saveAllAndFlush(theirs);
        // as on screen: n/a when the grade has no rate today and no claim that counts has a figure
        BigDecimal dueTotal = anyFigure || rates.findInForce(sheetId, person.gradeOn(today), today).isPresent() ? sheets.capped(sheetId, total) : null;
        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
        int count = (int) statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(s -> Objects.equals(s.getPersonId(), personId)).count();
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + money(dueTotal) + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        return new Taken(new Summary(personId, count, taken), theirs);
    }

    /**
     * Cancel the person's last statement: each claim it bound is unbound, so its figure is live
     * again. Refused (403) to anyone but a steward, and (409) for a person with no statement.
     */
    @Transactional
    public Cancelled cancel(String sheetId, String user, long personId) {
        roles.refuseViewer(sheetId, user);
        roles.refuseUnlessSteward(sheetId, user);
        Person person = people.lockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        List<Statement> theirStatements = statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(s -> Objects.equals(s.getPersonId(), personId)).toList();
        if (theirStatements.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " has no statement to cancel.");
        }
        Statement last = theirStatements.get(theirStatements.size() - 1);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        for (Claim claim : theirs) {
            if (claim.isStated()) {
                claim.bind(false, null);
            }
        }
        claims.saveAllAndFlush(theirs);
        statements.delete(last);
        statements.flush();
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + money(last.getDueTotal()));
        rollup.recordChanges(sheetId, user, before);
        int count = theirStatements.size() - 1;
        return new Cancelled(new Summary(personId, count, count == 0 ? null : theirStatements.get(count - 1)), theirs);
    }

    public static String money(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}
