283	        ClaimStatus was = claim.getStatus();
284	        // only a steward's review moves a PENDING claim on, other than voiding it
285	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
286	            throw new ResponseStatusException(HttpStatus.CONFLICT,
287	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
288	        }
289	        periods.refuseIfClosed(sheetId, claim.getDate());
290	        boolean reversing = was == ClaimStatus.SETTLED;
291	        if (reversing) {
292	            refuseVoidSettled(sheetId, user, claim);
293	        }
294	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
295	            throw new ResponseStatusException(HttpStatus.CONFLICT,
296	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
297	        }
298	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
299	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
300	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
301	        }
302	        if (review && !isSteward(sheetId, user)) {
303	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
304	                    "Only a steward can approve or reject a PENDING claim.");
305	        }
306	        Person person = person(sheetId, claim.getPersonId());
307	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
308	        // PENDING claim's figure is live)
309	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
310	        if (next == ClaimStatus.SETTLED && needsProof(sheetId, claim, settling)) {
311	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
312	                    "A claim due above the proof threshold cannot be " + (review ? "approved" : "settled")
313	                            + " without a proof.");
314	        }
315	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
316	            next = ClaimStatus.PENDING;
317	            settling = null;
318	        }
319	        claim.setStatus(next);
320	        if (next == ClaimStatus.OPEN && !review) {
321	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
322	            claim.setOpenedBy(user);
323	        } else if (next == ClaimStatus.SETTLED) {
324	            claim.setSettledDue(settling);
325	        }
326	        logStatus(sheetId, user, person, claim);
327	        Claim saved = claims.saveAndFlush(claim);
328	        String event = switch (next) {
329	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
330	            case PENDING -> "CLAIM_PENDING";
331	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
332	            case VOID -> "CLAIM_VOIDED";
333	            case DRAFT -> throw new IllegalStateException();
334	        };
335	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
336	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
337	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
338	                + (reason != null ? " reason=" + reason : "")
339	                + (reversing ? " reversed=" + dueText(saved.getSettledDue()) : ""));
340	        if (next == ClaimStatus.SETTLED) {
341	            notifyWatchers(sheetId, user, person, saved);
342	        }
343	        rollup.recordChanges(sheetId, user, before);
344	        return saved;
345	    }
