347	    /**
348	     * Refuse voiding a SETTLED claim: (403) for anyone but a steward, and (409) once the sheet's
349	     * today is more than {@value #VOID_SETTLED_DAYS} days after its settlement (or before it).
350	     */
351	    private void refuseVoidSettled(String sheetId, String user, Claim claim) {
352	        if (!isSteward(sheetId, user)) {
353	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a SETTLED claim.");
354	        }
355	        LocalDate settled = claim.getLog().stream().filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
356	                .map(ClaimLogEntry::getDate).reduce((first, last) -> last).orElse(null);
357	        LocalDate today = sheets.today(sheetId);
358	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
359	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can be voided only within "
360	                    + VOID_SETTLED_DAYS + " days of its settlement.");
361	        }
362	    }
