372	    /**
373	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
374	     * the claim counts in no total, is not overdue and cannot be settled; a statement it is bound
375	     * by stays as it is. Refused (409) for a claim that is not OPEN, (400) for a date
376	     * not after the sheet's today and (423) when dated inside a closed period.
377	     */
378	    @Transactional
379	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
380	        roles.refuseViewer(sheetId, user);
381	        RollupService.Snapshot before = rollup.snapshot(sheetId);
382	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
383	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
384	        if (claim.getStatus() != ClaimStatus.OPEN) {
385	            throw new ResponseStatusException(HttpStatus.CONFLICT,
386	                    "A " + claim.getStatus() + " claim cannot be deferred.");
387	        }
388	        if (!until.isAfter(sheets.today(sheetId))) {
389	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
390	                    "A claim can only be deferred to a date after the sheet's today.");
391	        }
392	        periods.refuseIfClosed(sheetId, claim.getDate());
393	        Person person = person(sheetId, claim.getPersonId());
394	        claim.setDeferredUntil(until);
395	        Claim saved = claims.saveAndFlush(claim);
396	        audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved)
397	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " until=" + until);
398	        rollup.recordChanges(sheetId, user, before);
399	        return saved;
400	    }
