424	    /**
425	     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
426	     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
427	     * steward, (409) for a claim that is not SETTLED and (423) when dated inside a closed period.
428	     */
429	    @Transactional
430	    public Claim resettle(String sheetId, String user, long id) {
431	        roles.refuseViewer(sheetId, user);
432	        if (!isSteward(sheetId, user)) {
433	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
434	        }
435	        RollupService.Snapshot before = rollup.snapshot(sheetId);
436	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
437	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
438	        if (claim.getStatus() != ClaimStatus.SETTLED) {
439	            throw new ResponseStatusException(HttpStatus.CONFLICT,
440	                    "A " + claim.getStatus() + " claim cannot be re-settled.");
441	        }
442	        periods.refuseIfClosed(sheetId, claim.getDate());
443	        Person person = person(sheetId, claim.getPersonId());
444	        BigDecimal old = claim.getSettledDue();
445	        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, due(sheetId, person, claim));
446	        claim.setSettledDue(settling);
447	        logStatus(sheetId, user, person, claim);
448	        Claim saved = claims.saveAndFlush(claim);
449	        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
450	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
451	                + " old=" + dueText(old) + " new=" + dueText(settling));
452	        notifyWatchers(sheetId, user, person, saved);
453	        rollup.recordChanges(sheetId, user, before);
454	        return saved;
455	    }
