457	    /**
458	     * Re-date an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure bound by a
459	     * statement stays bound; its period follows the new date. Under numbering per period, a claim
460	     * whose period changes takes the next number of its new period's sequence (or the X sequence in
461	     * no period); its old number is never given again. Refused (403) for anyone but a steward, (409)
462	     * for a claim that is not OPEN or PENDING, (423) when dated, or re-dated, inside a closed period
463	     * and (422) for a date after its person's retirement date.
464	     */
465	    @Transactional
466	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
467	        roles.refuseViewer(sheetId, user);
468	        if (!isSteward(sheetId, user)) {
469	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim.");
470	        }
471	        // lock the sheet's numbering before reading the claim, as opening one does
472	        Sheet sheet = sheets.lock(sheetId);
473	        RollupService.Snapshot before = rollup.snapshot(sheetId);
474	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
475	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
476	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
477	            throw new ResponseStatusException(HttpStatus.CONFLICT,
478	                    "A " + claim.getStatus() + " claim cannot be re-dated.");
479	        }
480	        LocalDate old = claim.getDate();
481	        periods.refuseIfClosed(sheetId, old);
482	        periods.refuseIfClosed(sheetId, date);
483	        Person person = person(sheetId, claim.getPersonId());
484	        refuseIfRetired(person, date);
485	        boolean renumber = sheet.numbersByPeriod()
486	                && !periods.periodNameOn(sheetId, old).equals(periods.periodNameOn(sheetId, date));
487	        claim.setDate(date);
488	        if (renumber) {
489	            claim.setNumber(sheets.nextClaimNumber(sheetId, date));
490	        }
491	        Claim saved = claims.saveAndFlush(claim);
492	        audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
493	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
494	                + " old=" + old + " new=" + date);
495	        rollup.recordChanges(sheetId, user, before);
496	        return saved;
497	    }
