499	    /**
500	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
501	     * date, is unbound from any statement (live again until its new person's next statement), and
502	     * is listed first under its new person. Refused (403) for a role the permission matrix does not allow, (409) for a SETTLED or VOID
503	     * claim or a move to the person it is already on, (400) for a correction (it must stay with
504	     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
505	     * the new person's retirement date.
506	     */
507	    @Transactional
508	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
509	        roles.refuseUnlessPermitted(sheetId, user, "reassign");
510	        RollupService.Snapshot before = rollup.snapshot(sheetId);
511	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
512	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
513	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
514	            throw new ResponseStatusException(HttpStatus.CONFLICT,
515	                    "A " + claim.getStatus() + " claim cannot be moved.");
516	        }
517	        Person from = person(sheetId, claim.getPersonId());
518	        Person to = person(sheetId, toPersonId);
519	        if (from.getId().equals(to.getId())) {
520	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
521	        }
522	        if (claim.isCorrection()) {
523	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
524	        }
525	        periods.refuseIfClosed(sheetId, claim.getDate());
526	        refuseIfRetired(to, claim.getDate());
527	        claim.setPersonId(to.getId());
528	        claim.bind(false, null);
529	        claims.saveAndFlush(claim);
530	        claims.listFirst(claim.getId());
531	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
532	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
533	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
534	                + " from=" + from.getName() + " to=" + to.getName());
535	        rollup.recordChanges(sheetId, user, before);
536	        return saved;
537	    }
