543	    /**
544	     * Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from
545	     * any statement; a new OPEN claim with the amount split off, the same date and note, the next
546	     * number, opened by the user and due by its date plus the terms in force on it, is listed first
547	     * under the person and shows the original's number as split-from. Refused (403) for a role that
548	     * may not open a claim, (409) for a claim that is not OPEN or is deferred, (400) for an amount
549	     * not above 0.00 and below the claim's, and (423) when dated inside a closed period.
550	     */
551	    @Transactional
552	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
553	        roles.refuseViewer(sheetId, user);
554	        roles.refuseUnlessPermitted(sheetId, user, "open");
555	        // lock the sheet's numbering before reading the claim, as opening one does
556	        sheets.lock(sheetId);
557	        RollupService.Snapshot before = rollup.snapshot(sheetId);
558	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
559	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
560	        if (claim.getStatus() != ClaimStatus.OPEN) {
561	            throw new ResponseStatusException(HttpStatus.CONFLICT,
562	                    "A " + claim.getStatus() + " claim cannot be split.");
563	        }
564	        if (claim.isDeferredOn(sheets.today(sheetId))) {
565	            throw new ResponseStatusException(HttpStatus.CONFLICT,
566	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then.");
567	        }
568	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
569	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
570	                    "A split must be more than 0.00 and less than the claim's amount.");
571	        }
572	        periods.refuseIfClosed(sheetId, claim.getDate());
573	        Person person = person(sheetId, claim.getPersonId());
574	        claim.setAmount(claim.getAmount().subtract(amount));
575	        claim.bind(false, null);
576	        Claim original = claims.saveAndFlush(claim);
577	        LocalDate dated = claim.getDate();
578	        Claim split = new Claim(sheetId, person.getId(), amount, dated,
579	                dueBy(sheetId, person, dated), claim.getNote(), null);
580	        split.setStatus(ClaimStatus.OPEN);
581	        split.setNumber(sheets.nextClaimNumber(sheetId, dated));
582	        split.setOpenedBy(user);
583	        split.setSplitFrom(original.getNumber());
584	        logStatus(sheetId, user, person, split);
585	        Claim added = claims.saveAndFlush(split);
586	        audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original)
587	                + " number=" + original.getNumber() + " into=" + added.getNumber());
588	        audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, added) + " number=" + added.getNumber());
589	        rollup.recordChanges(sheetId, user, before);
590	        return new Split(original, added);
591	    }
