593	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
594	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
595	    }
596	
597	    /**
598	     * Open the given claims together, in list order (the order people were added, newest claim
599	     * first within a person), so they are numbered in that order. A claim that cannot be opened
600	     * (not on the sheet, not DRAFT, or dated inside a closed period) is refused and left as it is.
601	     */
602	    @Transactional
603	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
604	        List<Claim> selected = inListOrder(sheetId, ids);
605	        int refused = (int) ids.stream().distinct().count() - selected.size();
606	        List<Claim> opened = new ArrayList<>();
607	        boolean permitted = sheets.sheet(sheetId).permits("open", roles.roleOf(sheetId, user));
608	        for (Claim claim : selected) {
609	            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())) {
610	                refused++;
611	                continue;
612	            }
613	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
614	        }
615	        return new BulkOpened(opened.size(), refused, opened);
616	    }
