618	    /** What a bulk settle did: how many claims were settled (or made PENDING) and how many refused, and the claims changed. */
619	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
620	    }
621	
622	    /**
623	     * Settle the given claims together, in list order (the order people were added, newest claim
624	     * first within a person), each by exactly the rules of settling one claim. A claim a clerk's
625	     * settle makes PENDING counts as settled; a claim that cannot be settled is refused and left
626	     * as it is.
627	     */
628	    @Transactional
629	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
630	        List<Claim> selected = inListOrder(sheetId, ids);
631	        int refused = (int) ids.stream().distinct().count() - selected.size();
632	        List<Claim> settled = new ArrayList<>();
633	        for (Claim claim : selected) {
634	            try {
635	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
636	            } catch (ResponseStatusException refusedOne) {
637	                // every refusal is checked before the claim is changed, so it is left as it is
638	                refused++;
639	            }
640	        }
641	        return new BulkSettled(settled.size(), refused, settled);
642	    }
