644	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
645	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
646	        Map<Long, Integer> personOrder = new HashMap<>();
647	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
648	        for (int i = 0; i < listed.size(); i++) {
649	            personOrder.put(listed.get(i).getId(), i);
650	        }
651	        return ids.stream().distinct()
652	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
653	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
654	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
655	                .toList();
656	    }
