658	    /**
659	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
660	     * rounded to the cent as the claim rounds (see {@link Rounding}), not raised to the floor (see {@link LateCharge});
661	     * null with no rate in force then.
662	     */
663	    public BigDecimal due(String sheetId, Person person, Claim claim) {
664	        Sheet sheet = sheets.sheet(sheetId);
665	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
666	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
667	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
668	                .orElse(null);
669	    }
670	
671	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
672	    private LocalDate roundingDate(String sheetId, Claim claim) {
673	        if (!claim.isCorrection() || claim.getCorrects() == null) {
674	            return claim.getDate();
675	        }
676	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
677	    }
