679	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
680	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
681	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
682	                dueText(charged(sheetId, person, claim))));
683	    }
684	
685	    private static String dueText(BigDecimal due) {
686	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
687	    }
