689	    /** Whether a claim settling at the figure is above the proof threshold in force on its date and has no proofs. */
690	    private boolean needsProof(String sheetId, Claim claim, BigDecimal figure) {
691	        BigDecimal threshold = sheets.sheet(sheetId).proofThresholdOn(claim.getDate());
692	        return claim.getProofs() == 0 && figure != null && threshold != null && figure.compareTo(threshold) > 0;
693	    }
694	
695	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
696	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
697	        BigDecimal limit = sheets.clerkLimit(sheetId);
698	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
699	    }
700	
701	    private boolean isSteward(String sheetId, String user) {
702	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
703	    }
