705	    /**
706	     * The number a claim corrects: none unless its amount is negative, when it must name the number
707	     * of a SETTLED claim of the same person, else it is refused (400).
708	     */
709	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
710	        if (amount.signum() >= 0) {
711	            return null;
712	        }
713	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
714	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
715	        if (!settled) {
716	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
717	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
718	        }
719	        return corrects;
720	    }
