722	    /** Refuse (422) a claim dated after its person's retirement date. */
723	    private static void refuseIfRetired(Person person, LocalDate date) {
724	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
725	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
726	                    "That claim's date is after its person's retirement date.");
727	        }
728	    }
