package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and their grades (A, B or C), each from a from-date, and the date they are retired from, if any;
 * and the holds they have had, each over a span of dates. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded, the first from the beginning of time (no from-date), the others each from a date. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedGrade> grades = new ArrayList<>();

    /** The person's own terms in days, or null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** Set once retired: the person counts as retired at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's OPEN claims dated within a hold, and not bound by a statement, count in no live total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<DatedHold> holds = new ArrayList<>();

    /** Bumped on every save; an edit must carry the version it was made from. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new DatedGrade(null, grade));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, the one from the beginning of time first and then by from-date. */
    public List<DatedGrade> getGrades() {
        return grades.stream().sorted(Comparator.comparing(DatedGrade::getFromDate,
                Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        String found = null;
        for (DatedGrade g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(date)) {
                found = g.getGrade();
            }
        }
        return found;
    }

    /** Record the grade from a date, replacing any grade already recorded from that same date. */
    public void setGradeFrom(LocalDate fromDate, String grade) {
        grades.removeIf(g -> fromDate.equals(g.getFromDate()));
        grades.add(new DatedGrade(fromDate, grade));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the retirement date is reached on a day (the day on or after it). */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** The holds recorded, by from-date. */
    public List<DatedHold> getHolds() {
        return holds.stream().sorted(Comparator.comparing(DatedHold::getFromDate)
                .thenComparing(DatedHold::getToDate, Comparator.nullsLast(Comparator.naturalOrder()))).toList();
    }

    public void addHold(LocalDate fromDate, LocalDate toDate) {
        holds.add(new DatedHold(fromDate, toDate));
    }

    /** Whether the person has any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether a day lies within one of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    /**
     * Whether a claim of this person counts toward the live totals: an open claim dated within a
     * hold does not, nor does one of a person whose retirement date the sheet's today has reached,
     * unless a statement binds it; nor does a claim deferred on the sheet's today.
     */
    public boolean counts(Claim claim, LocalDate today) {
        return counts(claim, claim.getStatus(), today);
    }

    /**
     * Whether a claim of this person counts by the same rules, had it the given status; a hold or a
     * reached retirement takes out only a claim that is open now as well (one since settled or voided is not).
     */
    public boolean counts(Claim claim, ClaimStatus status, LocalDate today) {
        return status.counts() && !claim.isDeferredOn(status, today) && (claim.isStated()
                || !(status.isOpen() && claim.getStatus().isOpen() && (heldOn(claim.getDate()) || retiredOn(today))));
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** One of a person's grades: in force from its from-date (none: from the beginning of time) until their next. */
@Embeddable
public class DatedGrade {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "grade", nullable = false)
    private String grade;

    protected DatedGrade() {
    }

    public DatedGrade(LocalDate fromDate, String grade) {
        this.fromDate = fromDate;
        this.grade = grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public String getGrade() {
        return grade;
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** One of a person's holds: from its from-date to its to-date (none: open-ended), both inclusive. */
@Embeddable
public class DatedHold {

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected DatedHold() {
    }

    public DatedHold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** Whether the day lies within the hold. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(fromDate) && (toDate == null || !date.isAfter(toDate));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The late charge on an overdue claim (OPEN or PENDING, and past its due-by on the sheet's today): for each full
 * 30 days it is overdue, the late percent in force on that boundary date (its due-by plus 30, 60, 90 ... days) of
 * its figure, rounded to the cent as the claim rounds (see {@link Rounding}), the charges added up. A correction has none. Never bound by a statement; settling a claim fixes it into its due.
 * The charge is worked out on the rate figure alone (or the figure a statement bound); the floor is applied last: a
 * claim's live due is the greater of the floor in force on its date and its figure plus its charge (a correction has
 * no floor).
 */
public final class LateCharge {

    /** The days overdue between boundaries that each add a late charge. */
    private static final int PERIOD_DAYS = 30;

    private LateCharge() {
    }

    /** The figure with its late charge added on top, then raised to the floor; null when the figure is null. */
    public static BigDecimal withCharge(Sheet sheet, Claim claim, BigDecimal figure) {
        return figure == null ? null : floored(sheet, claim, figure.add(charge(sheet, claim, figure)));
    }

    /**
     * The figure with the late charge it would have on the sheet's today were the claim open,
     * whatever its status; null when the figure is null.
     */
    public static BigDecimal withChargeAsOpen(Sheet sheet, Claim claim, BigDecimal figure) {
        return figure == null ? null : floored(sheet, claim, figure.add(charge(sheet, claim, figure, true)));
    }

    /** A due raised to the floor in force on the claim's date; a correction's is not. */
    private static BigDecimal floored(Sheet sheet, Claim claim, BigDecimal due) {
        return claim.isCorrection() ? due : due.max(sheet.floorOn(claim.getDate()));
    }

    /** The late charge on a claim's figure on the sheet's today; zero when it is not overdue. */
    public static BigDecimal charge(Sheet sheet, Claim claim, BigDecimal figure) {
        return charge(sheet, claim, figure, claim.getStatus().isOpen() && !claim.isDeferredOn(sheet.getToday()));
    }

    private static BigDecimal charge(Sheet sheet, Claim claim, BigDecimal figure, boolean open) {
        BigDecimal zero = BigDecimal.ZERO.setScale(2);
        if (figure == null || !open || claim.isCorrection()) {
            return zero;
        }
        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / PERIOD_DAYS;
        if (periods <= 0) {
            return zero;
        }
        RoundingMode mode = Rounding.mode(sheet, claim.getDate());
        BigDecimal total = zero;
        for (long k = 1; k <= periods; k++) {
            LocalDate boundary = claim.getDueBy().plusDays(k * PERIOD_DAYS);
            total = total.add(figure.multiply(sheet.latePctOn(boundary)).divide(BigDecimal.valueOf(100), 2, mode));
        }
        return total;
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Collection;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * How a claim's live figures are rounded to the cent: half up when the claim is dated before the
 * sheet's policy date (its today when it has none), half to even when dated on or after it. A
 * correction rounds by the date of the claim it corrects, not its own.
 */
public final class Rounding {

    private Rounding() {
    }

    /** The rounding for a claim dated on the given date. */
    public static RoundingMode mode(Sheet sheet, LocalDate date) {
        LocalDate policy = sheet.getPolicyDate() != null ? sheet.getPolicyDate() : sheet.getToday();
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The date a claim rounds by: its own, or for a correction the date of the claim it corrects,
     * found by number among the sheet's claims (its own when that claim is not among them).
     */
    public static LocalDate dateOf(Claim claim, Collection<Claim> sheetClaims) {
        if (!claim.isCorrection() || claim.getCorrects() == null) {
            return claim.getDate();
        }
        return sheetClaims.stream().filter(c -> claim.getCorrects().equals(c.getNumber())).findFirst()
                .map(Claim::getDate).orElse(claim.getDate());
    }
}

