44	    public record Snapshot(Map<Long, Figures> people) {
45	
46	        public BigDecimal claimedTotal() {
47	            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
48	        }
49	
50	        /** People's due-totals added up (n/a is no figure), trimmed as {@link #trimmed} says. */
51	        public BigDecimal dueTotal() {
52	            return trimmed(people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull).toList());
53	        }
54	
55	        /** People's overdue-totals added up, trimmed as {@link #trimmed} says. */
56	        public BigDecimal overdueTotal() {
57	            return trimmed(people.values().stream().map(Figures::overdueTotal).toList());
58	        }
59	
60	        /** The sum of people's figures, leaving out the single highest and lowest when there are three or more. */
61	        private static BigDecimal trimmed(List<BigDecimal> figures) {
62	            BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
63	            if (figures.size() < 3) {
64	                return sum;
65	            }
66	            return sum.subtract(figures.stream().reduce(BigDecimal::max).orElseThrow())
67	                    .subtract(figures.stream().reduce(BigDecimal::min).orElseThrow());
68	        }
69	    }
