77	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
78	            Audit audit) {
79	        this.people = people;
80	        this.claims = claims;
81	        this.rates = rates;
82	        this.sheets = sheets;
83	        this.audit = audit;
84	    }
