86	    /** The sheet's figures as the store holds them now. */
87	    public Snapshot snapshot(String sheetId) {
88	        Sheet sheet = sheet(sheetId);
89	        LocalDate today = sheet.getToday();
90	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
91	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
92	        Map<Long, Figures> figures = new LinkedHashMap<>();
93	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
94	            BigDecimal claimed = zero();
95	            BigDecimal due = zero();
96	            BigDecimal overdue = zero();
97	            boolean anyFigure = false;
98	            for (Claim claim : sheetClaims) {
99	                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim, today)) {
100	                    continue;
101	                }
102	                claimed = claimed.add(claim.getAmount());
103	                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
104	                if (figure != null) {
105	                    anyFigure = true;
106	                    due = due.add(figure);
107	                    if (overdue(claim, today)) {
108	                        overdue = overdue.add(figure);
109	                    }
110	                }
111	            }
112	            // as on screen: n/a when the grade in force today has no rate today and no claim that
113	            // counts has a figure
114	            boolean none = inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !anyFigure;
115	            figures.put(person.getId(), new Figures(person.getName(), claimed, none ? null : sheet.capped(due),
116	                    overdue));
117	        }
118	        return new Snapshot(figures);
119	    }
120	
121	    /**
122	     * Each person's due of their claims whose date falls in from..to (both inclusive) and that
123	     * counted by the status they had at the end of the to-day (as their status log records it; a
124	     * claim with none by then does not), by person id, for every person on the sheet (0.00 when
125	     * none). Each counts at its figure as shown now.
126	     */
127	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
128	        Sheet sheet = sheet(sheetId);
129	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
130	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
131	        Map<Long, BigDecimal> dues = new LinkedHashMap<>();
132	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
133	            BigDecimal due = zero();
134	            for (Claim claim : sheetClaims) {
135	                if (!claim.getPersonId().equals(person.getId()) || claim.getDate().isBefore(from)
136	                        || claim.getDate().isAfter(to) || !claim.statusAt(to)
137	                                .map(status -> person.counts(claim, status, sheet.getToday())).orElse(false)) {
138	                    continue;
139	                }
140	                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
141	                if (figure != null) {
142	                    due = due.add(figure);
143	                }
144	            }
145	            dues.put(person.getId(), due);
146	        }
147	        return dues;
148	    }
149	
150	    /** Record, once the change commits, the figures that moved since the snapshot taken before it. */
151	    public void recordChanges(String sheetId, String user, Snapshot before) {
152	        Snapshot after = snapshot(sheetId);
153	        String prefix = " sheet=" + sheetId + " by=" + user;
154	        boolean moved = false;
155	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
156	            Figures now = entry.getValue();
157	            Figures was = before.people().get(entry.getKey());
158	            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
159	                    && same(was.overdueTotal(), now.overdueTotal())) {
160	                continue;
161	            }
162	            moved = true;
163	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + money(now.claimed())
164	                    + " due-total=" + money(now.dueTotal()) + " overdue-total=" + money(now.overdueTotal()));
165	        }
166	        if (moved && !(same(before.claimedTotal(), after.claimedTotal())
167	                && same(before.dueTotal(), after.dueTotal()) && same(before.overdueTotal(), after.overdueTotal()))) {
168	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + money(after.claimedTotal()) + " due-total="
169	                    + money(after.dueTotal()) + " overdue-total=" + money(after.overdueTotal()));
170	        }
171	    }
172	
173	    /**
174	     * A claim's figure as the screen shows it: the due fixed when settled, else the one bound by the
175	     * last statement (not while PENDING), else its live due (rounded as the claim rounds, see {@link Rounding}), with its late charge added on top, then raised to the floor (a correction's is not);
176	     * null when none.
177	     */
178	    private static BigDecimal figure(Sheet sheet, List<Rate> sheetRates, List<Claim> sheetClaims, Person person,
179	            Claim claim) {
180	        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
181	            return claim.getSettledDue();
182	        }
183	        BigDecimal figure = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
184	                : inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
185	                        .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2,
186	                                Rounding.mode(sheet, Rounding.dateOf(claim, sheetClaims))))
187	                        .orElse(null);
188	        return LateCharge.withCharge(sheet, claim, figure);
189	    }
190	
191	    /** Whether a claim is overdue on the sheet's today: OPEN or PENDING, not deferred, and past its due-by. */
192	    private static boolean overdue(Claim claim, LocalDate today) {
193	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null && claim.getDueBy() != null
194	                && claim.getDueBy().isBefore(today);
195	    }
196	
197	    private Sheet sheet(String sheetId) {
198	        return sheets.findById(sheetId).orElseGet(() -> new Sheet(sheetId, null, null, LocalDate.now()));
199	    }
200	
201	    /** The grade's rate in force on a date, as {@link RateRepository#findInForce} picks it. */
202	    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
203	        return sheetRates.stream().filter(r -> r.getGrade().equals(grade))
204	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
205	                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
206	                        : a.getFromDate().compareTo(b.getFromDate()))
207	                .filter(r -> r.runsThrough(date));
208	    }
209	
210	    private static boolean same(BigDecimal a, BigDecimal b) {
211	        return a == null ? b == null : b != null && a.compareTo(b) == 0;
212	    }
213	
214	    private static BigDecimal zero() {
215	        return BigDecimal.ZERO.setScale(2);
216	    }
217	
218	    private static String money(BigDecimal value) {
219	        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
220	    }
221	}
