240	/** Loads a sheet by id; a sheet never loaded before is started empty, its today the real date. */
241	@Service
242	public class SheetService {
243	
244	    private final SheetRepository sheets;
245	    private final RollupService rollup;
246	    private final PeriodRepository periods;
247	    private final Audit audit;
248	    private final ClaimRepository claims;
