259	    @Transactional
260	    public Sheet load(String id, String user) {
261	        return sheets.findById(id).orElseGet(() -> {
262	            try {
263	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
264	            } catch (DataIntegrityViolationException e) {
265	                // another user started the same sheet at the same moment
266	                return sheets.findById(id).orElseThrow(() -> e);
267	            }
268	        });
269	    }
270	
271	    /** The sheet's today, for any date-dependent decision or default date on it. */
272	    @Transactional(readOnly = true)
273	    public LocalDate today(String id) {
274	        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
275	    }
276	
277	    /** The sheet as the store holds it now; a sheet never loaded reads as a new one, today the real date. */
278	    @Transactional(readOnly = true)
279	    public Sheet sheet(String id) {
280	        return sheets.findById(id).orElseGet(() -> new Sheet(id, null, null, LocalDate.now()));
281	    }
