283	    /** The sheet's clerk limit in force on its today: the most a clerk may settle a claim's due at; null for no limit. */
284	    @Transactional(readOnly = true)
285	    public BigDecimal clerkLimit(String id) {
286	        return sheets.findById(id).map(Sheet::getClerkLimit).orElse(null);
287	    }
