289	    /** A person's due-total held to the sheet's cap in force on its today (none: as it is; n/a stays n/a). */
290	    @Transactional(readOnly = true)
291	    public BigDecimal capped(String id, BigDecimal dueTotal) {
292	        return sheets.findById(id).map(s -> s.capped(dueTotal)).orElse(dueTotal);
293	    }
