295	    /** Refuse (423) any change to an archived sheet: it stays visible and may not be changed. */
296	    // a refusal leaves the caller's transaction usable (a bulk action refuses one claim and goes on)
297	    @Transactional(readOnly = true, noRollbackFor = ResponseStatusException.class)
298	    public void refuseIfArchived(String id) {
299	        if (sheet(id).isArchived()) {
300	            throw new ResponseStatusException(HttpStatus.LOCKED, "This sheet is archived and may not be changed.");
301	        }
302	    }
