304	    /** Archive the sheet; refused (409) when it is already archived. The caller checks the user is a steward. */
305	    @Transactional
306	    public Sheet archive(String id, String user) {
307	        load(id, user);
308	        Sheet sheet = lock(id);
309	        if (sheet.isArchived()) {
310	            throw new ResponseStatusException(HttpStatus.CONFLICT, "This sheet is already archived.");
311	        }
312	        sheet.archive();
313	        Sheet saved = sheets.saveAndFlush(sheet);
314	        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
315	        return saved;
316	    }
