318	    /** Lock the sheet until the caller's transaction ends; refused (404) when there is no such sheet. */
319	    @Transactional
320	    public Sheet lock(String id) {
321	        return sheets.findLockedById(id)
322	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
323	    }
324	
325	    /**
326	     * The next number for a claim dated {@code date} opened on the sheet, with no gaps and never
327	     * reused. Sheet-wide (1, 2, ...) unless the sheet numbers by period on its today: then within
328	     * the period the date falls in ({@code <period name>-<n>}), or in no period its X sequence
329	     * ({@code X-<n>}), each counting from 1. The sheet stays locked until the caller's transaction
330	     * ends, so two claims opened at the same moment take different numbers.
331	     */
332	    @Transactional
333	    public String nextClaimNumber(String id, LocalDate date) {
334	        Sheet sheet = lock(id);
335	        if (!sheet.numbersByPeriod()) {
336	            int number = sheet.nextClaimNumber();
337	            sheets.saveAndFlush(sheet);
338	            return String.valueOf(number);
339	        }
340	        Optional<Period> period = periods.findBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(id, date,
341	                date);
342	        if (period.isPresent()) {
343	            int number = period.get().nextClaimNumber();
344	            periods.saveAndFlush(period.get());
345	            return period.get().getName() + "-" + number;
346	        }
347	        int number = sheet.nextUnperiodClaimNumber();
348	        sheets.saveAndFlush(sheet);
349	        return "X-" + number;
350	    }
