352	    /**
353	     * Close an open period, fixing its due-total now, and record it ({@code auto=yes} when closed by
354	     * a change of the sheet's today). The caller holds the sheet.
355	     */
356	    @Transactional
357	    public Period closePeriod(String id, String user, Period period, boolean auto) {
358	        period.close(rollup.dueBetweenByPerson(id, period.getFromDate(), period.getToDate()));
359	        Period saved = periods.saveAndFlush(period);
360	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + id + " by=" + user + " period=" + saved.getName() + " total="
361	                + saved.getClosedDue().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + (auto ? " auto=yes" : ""));
362	        return saved;
363	    }
364	
365	    /** Soft-close an open period, fixing its due-total now, and record it. The caller holds the sheet. */
366	    @Transactional
367	    public Period softClosePeriod(String id, String user, Period period) {
368	        period.softClose(rollup.dueBetweenByPerson(id, period.getFromDate(), period.getToDate()));
369	        Period saved = periods.saveAndFlush(period);
370	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + id + " by=" + user + " period=" + saved.getName()
371	                + " total=" + saved.getClosedDue().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
372	        return saved;
373	    }
374	
375	    /**
376	     * Change the sheet's today. With grace days set, every open (not soft-closed) period whose to-date
377	     * plus the grace days is before the new today is then closed, in order of their to-dates. A new today releases
378	     * every claim editor's lock.
379	     */
380	    @Transactional
381	    public Sheet setToday(String id, String user, LocalDate today) {
382	        refuseIfArchived(id);
383	        load(id, user);
384	        // hold the sheet so no claim changes while periods close
385	        Sheet sheet = lock(id);
386	        RollupService.Snapshot before = rollup.snapshot(id);
387	        boolean moved = !today.equals(sheet.getToday());
388	        sheet.setToday(today);
389	        Sheet saved = sheets.saveAndFlush(sheet);
390	        Integer grace = saved.getGraceDays();
391	        if (grace != null) {
392	            for (Period period : periods.findBySheetIdAndClosedFalseOrderByToDateAsc(id)) {
393	                // a soft-closed period keeps the figures it fixed: only an open one closes by grace days
394	                if (!period.isSoftClosed() && period.getToDate().plusDays(grace).isBefore(today)) {
395	                    closePeriod(id, user, period, true);
396	                }
397	            }
398	        }
399	        // changing today has no audit line of its own, only the periods it closes and the figures it moves
400	        rollup.recordChanges(id, user, before);
401	        if (moved) {
402	            claims.unlockAll(id);
403	        }
404	        return saved;
405	    }
406	}
