423	/**
424	 * The sheet's periods: added on the screen, each a name unique on the sheet (without regard to
425	 * case) and a from and to date, both inclusive; no two periods on a sheet overlap. A period can be
426	 * closed once: closing fixes its due-total at that moment, and no claim dated inside a closed
427	 * period can be added, edited, opened, settled or voided. A steward can reopen a closed period, which
428	 * makes its due-total live again. A period can instead be soft-closed: its figures are fixed in the
429	 * same way but its claims can still change; it can then be closed (fixing them afresh) or reopened. With grace days set, a change of the sheet's today closes the
430	 * periods past them (see {@link SheetService#setToday}).
431	 */
432	@Service
433	public class PeriodService {
434	
435	    private final PeriodRepository periods;
436	    private final SheetService sheets;
437	    private final SheetRepository sheetRows;
438	    private final Audit audit;
439	    private final RoleService roles;
440	
441	    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows, Audit audit,
442	            RoleService roles) {
443	        this.roles = roles;
444	        this.periods = periods;
445	        this.sheets = sheets;
446	        this.sheetRows = sheetRows;
447	        this.audit = audit;
448	    }
