450	    @Transactional(readOnly = true)
451	    public List<Period> list(String sheetId) {
452	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
453	    }
454	
455	    @Transactional
456	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
457	        roles.refuseViewer(sheetId, user);
458	        if (to.isBefore(from)) {
459	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
460	        }
461	        sheets.load(sheetId, user);
462	        // hold the sheet so two periods added at the same moment are checked one after the other
463	        sheetRows.findLockedById(sheetId);
464	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
465	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
466	        }
467	        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
468	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
469	        }
470	        Period added;
471	        try {
472	            added = periods.saveAndFlush(new Period(sheetId, name, from, to));
473	        } catch (DataIntegrityViolationException e) {
474	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
475	        }
476	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
477	                + added.getFromDate() + " to=" + added.getToDate());
478	        return added;
479	    }
