481	    /**
482	     * Generate one period per calendar month from the from-date's month to the to-date's month, each
483	     * running from the first to the last day of its month and named yyyy-mm. A month whose name is
484	     * already a period, or whose days overlap a period on the sheet, is left out; the others are
485	     * still made. Refused (400) when the to-date is before the from-date.
486	     */
487	    @Transactional
488	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
489	        roles.refuseViewer(sheetId, user);
490	        if (to.isBefore(from)) {
491	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
492	        }
493	        sheets.load(sheetId, user);
494	        // hold the sheet so periods added at the same moment are checked one after the other
495	        sheetRows.findLockedById(sheetId);
496	        List<Period> made = new ArrayList<>();
497	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
498	            String name = month.toString();
499	            LocalDate first = month.atDay(1);
500	            LocalDate last = month.atEndOfMonth();
501	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)
502	                    || periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, last, first)) {
503	                continue;
504	            }
505	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
506	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName()
507	                    + " from=" + added.getFromDate() + " to=" + added.getToDate());
508	            made.add(added);
509	        }
510	        return made;
511	    }
512	
513	    /** Close a period, fixing its due-total now; refused (403) for a role the permission matrix does not allow and (409) when it is already closed. */
514	    @Transactional
515	    public Period close(String sheetId, String user, long id) {
516	        roles.refuseUnlessPermitted(sheetId, user, "close");
517	        // hold the sheet so no claim changes while the period's due-total is fixed
518	        sheetRows.findLockedById(sheetId)
519	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
520	        Period period = periods.findByIdAndSheetId(id, sheetId)
521	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
522	        if (period.isClosed()) {
523	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
524	        }
525	        return sheets.closePeriod(sheetId, user, period, false);
526	    }
527	
528	    /**
529	     * Soft-close a period, fixing its due-total and each person's now while claims dated inside it
530	     * can still change; refused (403) for a role the permission matrix does not allow to close and
531	     * (409) when it is already closed or soft-closed.
532	     */
533	    @Transactional
534	    public Period softClose(String sheetId, String user, long id) {
535	        roles.refuseUnlessPermitted(sheetId, user, "close");
536	        // hold the sheet so no claim changes while the period's due-total is fixed
537	        sheetRows.findLockedById(sheetId)
538	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
539	        Period period = periods.findByIdAndSheetId(id, sheetId)
540	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
541	        if (period.isClosed() || period.isSoftClosed()) {
542	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
543	        }
544	        return sheets.softClosePeriod(sheetId, user, period);
545	    }
546	
547	    /**
548	     * Reopen a closed or soft-closed period, making its due-total live again; refused (403) for a role the
549	     * permission matrix does not allow and (409) when the period is not closed.
550	     */
551	    @Transactional
552	    public Period reopen(String sheetId, String user, long id) {
553	        sheetRows.findLockedById(sheetId)
554	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
555	        Period period = periods.findByIdAndSheetId(id, sheetId)
556	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
557	        roles.refuseUnlessPermitted(sheetId, user, "reopen");
558	        if (!period.isClosed() && !period.isSoftClosed()) {
559	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
560	        }
561	        period.reopen();
562	        Period saved = periods.saveAndFlush(period);
563	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
564	        return saved;
565	    }
566	
567	    /**
568	     * Refuse (423) a change to a claim dated inside a closed period. Holds the sheet first, so a
569	     * period cannot close while the change is under way.
570	     */
571	    public void refuseIfClosed(String sheetId, LocalDate date) {
572	        if (isClosed(sheetId, date)) {
573	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period.");
574	        }
575	    }
576	
577	    /**
578	     * Whether a claim dated on this day lies inside a closed period. Holds the sheet first, so a
579	     * period cannot close while a change that relies on the answer is under way.
580	     */
581	    public boolean isClosed(String sheetId, LocalDate date) {
582	        sheetRows.findLockedById(sheetId);
583	        return periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date,
584	                date);
585	    }
586	
587	    /** Whether a claim dated on this day lies inside a soft-closed period. */
588	    public boolean isSoftClosed(String sheetId, LocalDate date) {
589	        return periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId,
590	                date, date);
591	    }
592	
593	    /** The name of the period the day falls in; blank when it falls in none. */
594	    public String periodNameOn(String sheetId, LocalDate date) {
595	        return periods.findBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)
596	                .map(Period::getName).orElse("");
597	    }
598	}
