617	/**
618	 * A period on a sheet: a name and a from and to date, both inclusive. A closed period keeps the
619	 * due-total it had when it was closed, and each person's due-total for it at that moment; so does a
620	 * soft-closed one, whose claims can still change.
621	 */
622	@Entity
623	@Table(name = "period")
624	public class Period {
625	
626	    @Id
627	    @GeneratedValue(strategy = GenerationType.IDENTITY)
628	    private Long id;
629	
630	    @Column(name = "sheet_id", nullable = false)
631	    private String sheetId;
632	
633	    @Column(name = "name", nullable = false)
634	    private String name;
635	
636	    @Column(name = "from_date", nullable = false)
637	    private LocalDate fromDate;
638	
639	    @Column(name = "to_date", nullable = false)
640	    private LocalDate toDate;
641	
642	    @Column(name = "closed", nullable = false)
643	    private boolean closed;
644	
645	    /** Soft-closed: the figures are fixed as for a closed period, but its claims can still change. */
646	    @Column(name = "soft_closed", nullable = false)
647	    private boolean softClosed;
648	
649	    @Column(name = "closed_due")
650	    private BigDecimal closedDue;
651	
652	    /** Each person's due-total fixed when the period was closed, by person id; empty while open. */
653	    @ElementCollection(fetch = FetchType.EAGER)
654	    @CollectionTable(name = "period_person_due", joinColumns = @JoinColumn(name = "period_id"))
655	    @MapKeyColumn(name = "person_id")
656	    @Column(name = "due", nullable = false)
657	    private Map<Long, BigDecimal> closedDues = new HashMap<>();
658	
659	    /** The last number given to a claim opened in this period under numbering per period. */
660	    @Column(name = "last_claim_number", nullable = false)
661	    private int lastClaimNumber;
662	
663	    protected Period() {
664	    }
665	
666	    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
667	        this.sheetId = sheetId;
668	        this.name = name;
669	        this.fromDate = fromDate;
670	        this.toDate = toDate;
671	    }
672	
673	    public Long getId() {
674	        return id;
675	    }
676	
677	    public String getSheetId() {
678	        return sheetId;
679	    }
680	
681	    public String getName() {
682	        return name;
683	    }
684	
685	    public LocalDate getFromDate() {
686	        return fromDate;
687	    }
688	
689	    public LocalDate getToDate() {
690	        return toDate;
691	    }
692	
693	    public boolean isClosed() {
694	        return closed;
695	    }
696	
697	    public boolean isSoftClosed() {
698	        return softClosed;
699	    }
700	
701	    public BigDecimal getClosedDue() {
702	        return closedDue;
703	    }
704	
705	    public Map<Long, BigDecimal> getClosedDues() {
706	        return closedDues;
707	    }
708	
709	    /** Give out the next claim number within this period. */
710	    public int nextClaimNumber() {
711	        return ++lastClaimNumber;
712	    }
713	
714	    /**
715	     * Close the period, fixing each person's due-total for it at this moment; its own due-total is
716	     * their sum.
717	     */
718	    public void close(Map<Long, BigDecimal> dues) {
719	        fix(dues);
720	        this.closed = true;
721	        this.softClosed = false;
722	    }
723	
724	    /**
725	     * Soft-close the period, fixing its figures as {@link #close} does while its claims can still
726	     * change.
727	     */
728	    public void softClose(Map<Long, BigDecimal> dues) {
729	        fix(dues);
730	        this.softClosed = true;
731	    }
732	
733	    private void fix(Map<Long, BigDecimal> dues) {
734	        this.closedDues.clear();
735	        this.closedDues.putAll(dues);
736	        this.closedDue = dues.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
737	    }
738	
739	    /** Reopen the period: its due-total is live again. */
740	    public void reopen() {
741	        this.closed = false;
742	        this.softClosed = false;
743	        this.closedDue = null;
744	        this.closedDues.clear();
745	    }
746	}
747	package net.officefloor.hq.app.person;
748	
749	import java.time.LocalDate;
750	import java.util.List;
751	import java.util.Objects;
752	import net.officefloor.hq.app.Audit;
753	import net.officefloor.hq.app.role.RoleService;
754	import net.officefloor.hq.app.rollup.RollupService;
755	import net.officefloor.hq.app.sheet.SheetService;
756	import org.springframework.dao.DataIntegrityViolationException;
757	import org.springframework.orm.ObjectOptimisticLockingFailureException;
758	import org.springframework.http.HttpStatus;
759	import org.springframework.stereotype.Service;
760	import org.springframework.transaction.annotation.Transactional;
761	import org.springframework.web.server.ResponseStatusException;
762	
763	/**
764	 * The people on a sheet: listed in the order they were added, added and edited by name and grade. A
765	 * person's grade is dated: the first applies from the beginning of time, and each edit records the
766	 * grade from its from-date (the sheet's today when none is given), keeping those already recorded;
767	 * an edit leaving the grade in force on the sheet's today as it is, with no from-date, records none.
768	 * A
769	 * name is unique on the sheet, compared without regard to case (names arrive trimmed). A person can
770	 * be retired from a date (the sheet's today when none is given); they count as retired at once. A
771	 * person can be put on hold over a span of dates, and may have several holds over time. A person can name other people on the sheet as
772	 * their patrons, one at a time: not themselves, and not the same person twice. A user can watch a
773	 * person, and stop watching them; each user's watching is their own. A person may have their own
774	 * terms, in days; a claim's due-by takes them before the terms of the person's grade and the sheet's.
775	 */
776	@Service
777	public class PersonService {
778	
779	    private final PersonRepository people;
780	    private final SheetService sheets;
781	    private final Audit audit;
782	    private final RollupService rollup;
783	    private final PatronRepository patrons;
784	    private final RoleService roles;
785	    private final WatchRepository watches;
786	
787	    public PersonService(PersonRepository people, SheetService sheets, Audit audit, RollupService rollup,
788	            PatronRepository patrons, RoleService roles, WatchRepository watches) {
789	        this.roles = roles;
790	        this.watches = watches;
791	        this.people = people;
792	        this.patrons = patrons;
793	        this.sheets = sheets;
794	        this.audit = audit;
795	        this.rollup = rollup;
796	    }
797	
798	    @Transactional(readOnly = true)
799	    public List<Person> list(String sheetId) {
800	        return people.findBySheetIdOrderByIdAsc(sheetId);
801	    }
802	
803	    @Transactional
804	    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
805	        roles.refuseViewer(sheetId, user);
806	        sheets.load(sheetId, user);
807	        RollupService.Snapshot before = rollup.snapshot(sheetId);
808	        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
809	            throw nameInUse();
810	        }
811	        Person person = new Person(sheetId, name, grade);
812	        person.setTerms(terms);
813	        Person added = save(person);
814	        audit.recordOnCommit(record("PERSON_ADDED", sheetId, user, added, sheets.today(sheetId))
815	                + (terms != null ? " terms=" + terms : ""));
816	        rollup.recordChanges(sheetId, user, before);
817	        return added;
818	    }
819	
820	    @Transactional
821	    public Person update(String sheetId, String user, long id, long version, String name, String grade,
822	            LocalDate gradeFrom, Integer terms) {
823	        roles.refuseViewer(sheetId, user);
824	        RollupService.Snapshot before = rollup.snapshot(sheetId);
825	        Person person = people.findByIdAndSheetId(id, sheetId)
826	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
827	        if (person.getVersion() != version) {
828	            throw stale();
829	        }
830	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, name, id)) {
831	            throw nameInUse();
832	        }
833	        LocalDate today = sheets.today(sheetId);
834	        Integer termsBefore = person.getTerms();
835	        person.setName(name);
836	        person.setTerms(terms);
837	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
838	            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade);
839	        }
840	        Person saved = save(person);
841	        audit.recordOnCommit(record("PERSON_EDITED", sheetId, user, saved, today)
842	                + (Objects.equals(termsBefore, terms) ? "" : " terms=" + (terms != null ? terms : "")));
843	        rollup.recordChanges(sheetId, user, before);
844	        return saved;
845	    }
846	
847	    /**
848	     * Retire the person from a date, or from the sheet's today when none is given. Once the sheet's
849	     * today reaches that date their OPEN claims leave every live total, so the figures that move are recorded.
850	     */
851	    @Transactional
852	    public Person retire(String sheetId, String user, long id, LocalDate date) {
853	        roles.refuseViewer(sheetId, user);
854	        Person person = people.findByIdAndSheetId(id, sheetId)
855	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
856	        RollupService.Snapshot before = rollup.snapshot(sheetId);
857	        LocalDate from = date != null ? date : sheets.today(sheetId);
858	        person.setRetiredFrom(from);
859	        Person saved = save(person);
860	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
861	                + from);
862	        rollup.recordChanges(sheetId, user, before);
863	        return saved;
864	    }
865	
866	    /**
867	     * Put the person on hold from a date (the sheet's today when none is given) to an optional
868	     * to-date; refused (400) when the to-date is before the from-date. Their OPEN claims dated within
869	     * the hold leave every live total, so the figures that move are recorded.
870	     */
871	    @Transactional
872	    public Person hold(String sheetId, String user, long id, LocalDate fromDate, LocalDate toDate) {
873	        roles.refuseViewer(sheetId, user);
874	        RollupService.Snapshot before = rollup.snapshot(sheetId);
875	        Person person = people.lockByIdAndSheetId(id, sheetId)
876	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
877	        LocalDate from = fromDate != null ? fromDate : sheets.today(sheetId);
878	        if (toDate != null && toDate.isBefore(from)) {
879	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
880	        }
881	        person.addHold(from, toDate);
882	        Person saved = save(person);
883	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName() + " from="
884	                + from);
885	        rollup.recordChanges(sheetId, user, before);
886	        return saved;
887	    }
888	
889	    @Transactional(readOnly = true)
890	    public List<Patron> patrons(String sheetId) {
891	        return patrons.findBySheetIdOrderByIdAsc(sheetId);
892	    }
893	
894	    /**
895	     * Name another person on the sheet as the person's patron; refused (409) when it is the person
896	     * themselves or already one of their patrons.
897	     */
898	    @Transactional
899	    public Patron addPatron(String sheetId, String user, long id, long patronId) {
900	        roles.refuseViewer(sheetId, user);
901	        Person person = people.findByIdAndSheetId(id, sheetId)
902	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
903	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
904	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
905	        if (person.getId().equals(patron.getId())) {
906	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
907	        }
908	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
909	            throw patronTaken();
910	        }
911	        Patron added;
912	        try {
913	            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
914	        } catch (DataIntegrityViolationException e) {
915	            throw patronTaken();
916	        }
917	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
918	                + " patron=" + patron.getName());
919	        return added;
920	    }
921	
922	    /** The ids of the people the user watches on the sheet. */
923	    @Transactional(readOnly = true)
924	    public List<Long> watched(String sheetId, String user) {
925	        return watches.findBySheetIdAndUserName(sheetId, user).stream().map(Watch::getPersonId).toList();
926	    }
927	
928	    /**
929	     * Start ({@code on}) or stop watching the person as the user; already so, nothing changes and
930	     * nothing is recorded.
931	     */
932	    @Transactional
933	    public void watch(String sheetId, String user, long id, boolean on) {
934	        sheets.refuseIfArchived(sheetId);
935	        Person person = people.lockByIdAndSheetId(id, sheetId)
936	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
937	        var existing = watches.findByPersonIdAndUserName(person.getId(), user);
938	        if (on == existing.isPresent()) {
939	            return;
940	        }
941	        if (on) {
942	            watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
943	        } else {
944	            watches.delete(existing.get());
945	            watches.flush();
946	        }
947	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
948	                + " name=" + person.getName());
949	    }
950	
951	    private static ResponseStatusException patronTaken() {
952	        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
953	    }
954	
955	    /** A person's record, with the grade in force on the sheet's today. */
956	    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
957	        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
958	                + person.gradeOn(today);
959	    }
960	
961	    /**
962	     * Save, refusing a name another user took on the sheet since it was checked, and an edit another
963	     * user saved over since the person was read.
964	     */
965	    private Person save(Person person) {
966	        try {
967	            return people.saveAndFlush(person);
968	        } catch (DataIntegrityViolationException e) {
969	            throw nameInUse();
970	        } catch (ObjectOptimisticLockingFailureException e) {
971	            throw stale();
972	        }
973	    }
974	
975	    /** The edit was made from a version of the person that another user has since saved over. */
976	    private static ResponseStatusException stale() {
977	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
978	                "Someone else has saved this person since it was opened.");
979	    }
980	
981	    private static ResponseStatusException nameInUse() {
982	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
983	    }
984	}
